#requires -Version 7.0
# ============================================================================
#  VIA-OneShot v0100  --  一支自解壓, 含全部引擎, 貼一個檔就跑完整條
# ----------------------------------------------------------------------------
#  本檔內嵌全部引擎 (base64). 執行時: 解出引擎 -> 弄 Python -> 裝依賴 ->
#  建 DB/SSOT -> 跑管線 (郵件/②/①/③/探勘) -> 出 UI. 零外部檔案依賴.
#  政策: Python 預設 detect-only; -AllowInstall 才可攜式安裝 (免管理員, 不動系統).
#  慣例: param 首列; 無別名; 無 Read-Host; 無 exit; ProcessStartInfo; UTF8 no-BOM.
# ============================================================================
param(
    [string]$Workbench = "",
    [switch]$AllowInstall,
    [switch]$NoActivate,
    [switch]$NoOpen
)
$ErrorActionPreference = 'Stop'
$script:T0 = Get-Date
if (-not $Workbench) { $base = Split-Path -Parent $PSCommandPath; if (-not $base) { $base = (Get-Location).Path }; $Workbench = Join-Path $base "VIA_OneShot_Home" }
$EngDir    = Join-Path $Workbench 'engines'
$DataDir   = Join-Path $Workbench 'data'
$ReportDir = Join-Path $Workbench 'reports'
foreach ($d in @($Workbench,$EngDir,$DataDir,$ReportDir)) { if (-not (Test-Path $d)) { New-Item -ItemType Directory -Path $d -Force | Out-Null } }
function Say { param([string]$T,[string]$M,[string]$C='Cyan') Write-Host ('[{0}] [{1}] {2}' -f (Get-Date).ToString('HH:mm:ss'),$T,$M) -ForegroundColor $C }
function Save-TextFile { param([string]$Path,[string]$Text) [System.IO.File]::WriteAllText($Path,$Text,[System.Text.UTF8Encoding]::new($false)) }
function Invoke-Native { param([string]$FilePath,[string[]]$Arguments)
    $psi=[System.Diagnostics.ProcessStartInfo]::new(); $psi.FileName=$FilePath
    foreach ($a in $Arguments) { [void]$psi.ArgumentList.Add($a) }
    $psi.RedirectStandardOutput=$true; $psi.RedirectStandardError=$true; $psi.UseShellExecute=$false; $psi.CreateNoWindow=$true
    $p=[System.Diagnostics.Process]::new(); $p.StartInfo=$psi
    try { [void]$p.Start() } catch { return @{code=-999;out='';err=$_.Exception.Message} }
    $o=$p.StandardOutput.ReadToEnd(); $e=$p.StandardError.ReadToEnd(); $p.WaitForExit()
    return @{code=$p.ExitCode;out=$o;err=$e} }

Write-Host ''
Write-Host '=============================================================' -ForegroundColor DarkCyan
Write-Host '  VIA-OneShot v0100  |  一支自解壓, 含全部引擎' -ForegroundColor Cyan
Write-Host '=============================================================' -ForegroundColor DarkCyan

# --- 內嵌引擎 (base64) ---
$EMBEDDED = @{
  'Invoke-VIA-CommandCenter-v0100.ps1' = ''
  'Invoke-VIA-PythonRuntime-Bootstrap-v0100.ps1' = ''
  'VIA_EnvManager_Deploy_VMT.ps1' = ''
  'VIA_ENG020_SuperBOMContentParser_v0100.py' = ''
  'VeritasMailTracker_v1.ps1' = ''
  'super_bom_ssot_template.sql' = ''
  'VIA_ENG024_VmtProcessMining.py' = ''
  'VIA_ENG025_VmtReplyIngest.py' = ''
  'VIA_ENG026_VmtSuperbomAttachRouter.py' = ''
  'VIA_ENG027_VmtSuperbomBridge.py' = ''
  'VIA_ENG028_VmtSuperbomEventstream.py' = ''
}
Say '1/7' ('解出內嵌引擎: ' + $EMBEDDED.Count + ' 檔 -> ' + $EngDir) 'Green'
foreach ($k in $EMBEDDED.Keys) { [System.IO.File]::WriteAllBytes((Join-Path $EngDir $k), [Convert]::FromBase64String($EMBEDDED[$k])) }

$commandCenter = Join-Path $EngDir 'Invoke-VIA-CommandCenter-v0100.ps1'
$bootstrap     = Join-Path $EngDir 'Invoke-VIA-PythonRuntime-Bootstrap-v0100.ps1'
$parser        = Join-Path $EngDir 'VIA_ENG020_SuperBOMContentParser_v0100.py'
$sqlTemplate   = Join-Path $EngDir 'super_bom_ssot_template.sql'

# --- Python 偵測 (拒 Store 別名); 缺且授權則 bootstrap 可攜式 ---
function Resolve-RealPy {
    $cfg = Join-Path $DataDir 'python_runtime.json'
    $cands=@(); if (Test-Path $cfg) { try { $j=Get-Content $cfg -Raw -Encoding UTF8|ConvertFrom-Json; if ($j.python){$cands+=$j.python} } catch {} }
    $cands += @('py','python3','python')
    foreach ($c in $cands) { if (-not $c){continue}
        $r=Invoke-Native -FilePath $c -Arguments @('--version'); $o=($r.out+$r.err)
        if ($r.code -eq 0 -and $o -match 'Python\s+3' -and $o -notmatch 'Microsoft Store|WindowsApps|was not found') { return $c } }
    return $null }
$py = Resolve-RealPy
if (-not $py -and $AllowInstall) {
    Say '2/7' '無 Python 且已授權 -> bootstrap 可攜式安裝' 'Cyan'
    $null = Invoke-Native -FilePath 'pwsh' -Arguments @('-NoProfile','-File',$bootstrap,'-Workbench',$Workbench,'-AuthorizeInstall','-NoOpen')
    $py = Resolve-RealPy
} elseif (-not $py) { $null = Invoke-Native -FilePath 'pwsh' -Arguments @('-NoProfile','-File',$bootstrap,'-Workbench',$Workbench,'-NoOpen') }
if ($py) { Say '2/7' ('Python 就緒: '+$py) 'Green' } else { Say '2/7' 'Python 缺席 — 只做 PS 半邊 + UI' 'Yellow' }

# --- 依賴 ---
$depsOk=$false
if ($py) { Say '3/7' '裝依賴 duckdb pandas' 'Cyan'
    $null = Invoke-Native -FilePath $py -Arguments @('-m','pip','install','--quiet','duckdb','pandas')
    $chk = Invoke-Native -FilePath $py -Arguments @('-c','import duckdb,pandas;print(1)'); $depsOk = ($chk.out -match '1')
    if ($depsOk) { Write-Host '    duckdb+pandas OK' -ForegroundColor Green } else { Write-Host '    依賴未完成' -ForegroundColor Yellow } }

# --- 備 DB (append-only) ---
$sbomDb = Join-Path $Workbench 'superbom.duckdb'
if ($py -and $depsOk -and -not (Test-Path $sbomDb)) { Say '4/7' '建 superbom.duckdb' 'Cyan'
    $mk = Invoke-Native -FilePath $py -Arguments @('-c',("import duckdb;duckdb.connect(r'{0}').execute(open(r'{1}',encoding='utf-8').read())" -f $sbomDb,$sqlTemplate))
    if ($mk.code -eq 0){Write-Host '    OK' -ForegroundColor Green}else{Write-Host ('    警告: '+($mk.err.Trim()-split "`n"|Select-Object -Last 1)) -ForegroundColor Yellow} }
elseif (Test-Path $sbomDb) { Say '4/7' 'superbom.duckdb 已存在' 'Green' }

# --- 備 ssot.json (append-only, 14 案) ---
$ssot = Join-Path $DataDir 'ssot.json'
if (-not (Test-Path $ssot)) { Say '5/7' '建 ssot.json (14 案)' 'Cyan'
    $cases = 1..14 | ForEach-Object { @{id=('CASE-{0:D2}' -f $_);name=('Case {0:D2}' -f $_);status='ACTIVE'} }
    $obj = @{meta=@{system='VeritasMailTracker'};counters=@{issue=0;mail=0};cases=$cases;issues=@()}
    Save-TextFile -Path $ssot -Text ($obj|ConvertTo-Json -Depth 6) }
else { Say '5/7' 'ssot.json 已存在' 'Green' }

# --- 郵件 SSOT (PS, 免 Python) 先跑一次產生郵件儀表板 ---
$mailer = Join-Path $EngDir 'VeritasMailTracker_v1.ps1'
if (Test-Path $mailer) { Say '6/7' '跑郵件 SSOT (PS 半邊)' 'Cyan'
    $null = Invoke-Native -FilePath 'pwsh' -Arguments @('-NoProfile','-File',$mailer,'-Root',$Workbench,'-NoOpen') }

# --- 交棒 Command Center: 健檢 + 啟用管線 + UI ---
Say '7/7' '交棒 Command Center' 'Cyan'
$op = if ($env:USERNAME) { $env:USERNAME } elseif ($env:USER) { $env:USER } else { 'operator' }
$ccArgs = @('-NoProfile','-File',$commandCenter,'-Workbench',$Workbench,'-SearchRoot',$EngDir,'-VmtRoot',$Workbench,'-Operator',$op,'-NoOpen')
if ($py) { $ccArgs += @('-PyExe',$py) }
if (Test-Path $sbomDb) { $ccArgs += @('-SbomDb',$sbomDb) }
$ccArgs += @('-Parser',$parser)
if ($py -and $depsOk -and -not $NoActivate) { $ccArgs += @('-Activate','-Commit') }
$cc = Invoke-Native -FilePath 'pwsh' -Arguments $ccArgs
Write-Host ($cc.out.Trim()) -ForegroundColor Gray

$router = Join-Path $ReportDir 'VIA_CommandCenter.html'
$sec = [math]::Round(((Get-Date)-$script:T0).TotalSeconds,1)
Write-Host ''
if ($py -and $depsOk) { Write-Host ('  全部完成 ('+$sec+'s). 引擎/Python/依賴/DB/SSOT/管線/UI 全就緒。') -ForegroundColor Green }
else { Write-Host ('  前置完成 ('+$sec+'s). 引擎已自解出; 補 Python 後重跑即全綠 (加 -AllowInstall 或先 winget install Python.Python.3.12)。') -ForegroundColor Yellow }
Write-Host ('  入口: '+$router) -ForegroundColor Yellow
Write-Host ''
if ((-not $NoOpen) -and (Test-Path $router)) { Start-Process $router }

# ===== [VIA:PS-ACCEL:v0100] 20 加速器導入註記(批102 令;零執行純註解) =====
# 本檔已登記導入 VIA 20 加速器冊(01 AST/02 語意/03 Hydra/04 拓撲/05 沙盒/
# 06 修正建議/07 全景/08 SSOT/09 矩陣/10 分群/11 性能/12 同步/13 回滾/
# 14 覆蓋率/15 排程/16 進度條/17 說明/18 非阻塞/19 多引擎/20 部署)。
# 實體模組:supportive modules\VIA_PS_Accel_Module.ps1(dot-source 取用
